1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	}
66	
67	const ITEM_SPECS = {
68	  sword: { basePremium: 100, insuranceValue: 1000 },
69	  amulet: { basePremium: 60, insuranceValue: 600 },
70	  staff: { basePremium: 80, insuranceValue: 800 },
71	  potion: { basePremium: 40, insuranceValue: 400 },
72	  rune: { basePremium: 25, insuranceValue: 250 },
73	  moonstone: { basePremium: 25, insuranceValue: 250 },
74	} as const satisfies Record<string, ItemSpec>;
75	
76	type KnownItemType = keyof typeof ITEM_SPECS;
77	
78	const isKnownItemType = (type: string): type is KnownItemType =>
79	  type in ITEM_SPECS;
80	
81	// Unknown item types are not yet rejected — the spec requires an error, but no
82	// test drives that behaviour yet, so they carry zeroes for the moment.
83	const UNKNOWN_TYPE_SPEC: ItemSpec = { basePremium: 0, insuranceValue: 0 };
84	
85	const specForItem = (item: Item): ItemSpec =>
86	  isKnownItemType(item.type) ? ITEM_SPECS[item.type] : UNKNOWN_TYPE_SPEC;
87	
88	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
89	
90	const BLOCK_SIZE = 3;
91	
92	const BLOCK_BASE_PREMIUM = 60;
93	
94	const sum = (amounts: number[]): number =>
95	  amounts.reduce((total, amount) => total + amount, 0);
96	
97	// "Alike" means the same exact type, not merely the same family: two runes and
98	// a moonstone are three components but not three alike ones, so grouping them
99	// by type keeps them apart and denies them the block price.
100	const groupByType = (items: Item[]): Item[][] => {
101	  const groups = new Map<string, Item[]>();
102	  for (const item of items) {
103	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
104	  }
105	  return [...groups.values()];
106	};
107	
108	// A block is not carved out of a larger group: the block price applies only
109	// when the group consists of exactly three alike components (7 runes cost
110	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
111	// ever passes a single group from groupByType.
112	const basePremiumForGroup = (group: Item[]): number =>
113	  group.length === BLOCK_SIZE
114	    ? BLOCK_BASE_PREMIUM
115	    : sum(group.map(basePremiumForItem));
116	
117	const basePremiumForItems = (items: Item[]): number =>
118	  sum(groupByType(items).map(basePremiumForGroup));
119	
120	const CURSE_SURCHARGE = 0.5;
121	
122	// Every modifier is an additive percentage of its OWN base — modifiers never
123	// compound with each other. Item-scoped modifiers take the affected item's base
124	// premium as their base; policy-scoped modifiers take the policy base premium
125	// (the sum of all item base premiums). So the total is always
126	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
127	const modifierAmount = (rate: number, base: number): number => rate * base;
128	
129	const ENCHANTMENT_SURCHARGE = 0.3;
130	
131	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
132	
133	const isCursed = (item: Item): boolean => item.cursed === true;
134	
135	const attractsEnchantmentSurcharge = (item: Item): boolean =>
136	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
137	
138	interface ItemModifier {
139	  rate: number;
140	  appliesTo: (item: Item) => boolean;
141	}
142	
143	// Each item-scoped modifier is a row: a rate and the condition under which it
144	// applies. The predicate names the modifier, so a row needs no separate label.
145	// Adding a modifier means adding a row, not a new branch.
146	const ITEM_MODIFIERS: ItemModifier[] = [
147	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
148	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
149	];
150	
151	const itemModifierRates = (item: Item): number[] =>
152	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
153	    (modifier) => modifier.rate,
154	  );
155	
156	const LOYALTY_DISCOUNT = 0.2;
157	
158	const LOYALTY_THRESHOLD_YEARS = 2;
159	
160	const isLongStanding = (customer: Customer): boolean =>
161	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
162	
163	// Discounts are surcharges with the sign flipped: expressing one as a negative
164	// rate lets it flow through the same additive sum as every surcharge, with no
165	// separate subtraction step. Discount constants stay positive magnitudes and
166	// are negated here, at the point of use, so the direction is visible in the
167	// rate list rather than buried in a constant's sign.
168	const asDiscount = (rate: number): number => -rate;
169	
170	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
171	
172	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
173	
174	// Policy-scoped modifiers apply to the policy base premium. Unlike item
175	// modifiers they select on the customer and on the quote's position in the
176	// scenario rather than on an item.
177	//
178	// The initial-assessment surcharge applies to every quote: each item is treated
179	// as a first insurance regardless of customer history. The follow-up discount
180	// is what distinguishes a customer's later contracts.
181	const policyModifierRates = (
182	  customer: Customer,
183	  isFollowUpContract: boolean,
184	): number[] => [
185	  INITIAL_ASSESSMENT_SURCHARGE,
186	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
187	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
188	];
189	
190	const itemModifiersTotal = (items: Item[]): number =>
191	  sum(
192	    items.flatMap((item) =>
193	      itemModifierRates(item).map((rate) =>
194	        modifierAmount(rate, basePremiumForItem(item)),
195	      ),
196	    ),
197	  );
198	
199	const policyModifiersTotal = (
200	  policyBasePremium: number,
201	  customer: Customer,
202	  isFollowUpContract: boolean,
203	): number =>
204	  sum(
205	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
206	      modifierAmount(rate, policyBasePremium),
207	    ),
208	  );
209	
210	// All amounts are rounded to whole G in the MHPCO's favour. For a premium —
211	// money flowing to the MHPCO — its favour is upwards. The payout half of this
212	// rule rounds the other way, but no test drives payouts yet, so only the
213	// premium direction is named here.
214	const roundPremiumInMHPCOsFavour = (amount: number): number =>
215	  Math.ceil(amount);
216	
217	const quotePremium = (
218	  items: Item[],
219	  customer: Customer,
220	  isFollowUpContract: boolean,
221	): number => {
222	  const policyBasePremium = basePremiumForItems(items);
223	  return roundPremiumInMHPCOsFavour(
224	    policyBasePremium +
225	      itemModifiersTotal(items) +
226	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
227	      PROCESSING_FEE,
228	  );
229	};
230	
231	const insuranceValueForItem = (item: Item): number =>
232	  specForItem(item).insuranceValue;
233	
234	const insuranceSum = (items: Item[]): number =>
235	  sum(items.map(insuranceValueForItem));
236	
237	const CAP_MULTIPLE = 2;
238	
239	const DEDUCTIBLE = 100;
240	
241	interface Policy {
242	  items: Item[];
243	  remainingCap: number;
244	}
245	
246	// Steps are not independent: a quote's premium depends on how many quotes came
247	// before it, and a claim draws down the cap of a policy an earlier quote
248	// created. So a step is a function from state to (result, next state), and the
249	// scenario is a fold over that — not a map, which would promise an independence
250	// the steps do not have.
251	//
252	// Policies are keyed by the index of the quote step that created them: a claim
253	// step names its policy by that zero-based index.
254	interface ScenarioState {
255	  quotesSoFar: number;
256	  policies: Map<number, Policy>;
257	}
258	
259	const INITIAL_STATE: ScenarioState = {
260	  quotesSoFar: 0,
261	  policies: new Map(),
262	};
263	
264	interface StepOutcome {
265	  result: StepResult;
266	  state: ScenarioState;
267	}
268	
269	// Both operations end by filing a policy under its quote's index — a claim
270	// re-files the same policy with a drawn-down cap. Naming that once keeps the
271	// Map out of the operations, so neither has to know how policies are stored.
272	const withPolicy = (
273	  state: ScenarioState,
274	  policyIndex: number,
275	  policy: Policy,
276	): ScenarioState => ({
277	  ...state,
278	  policies: new Map(state.policies).set(policyIndex, policy),
279	});
280	
281	const runQuote = (
282	  step: QuoteStep,
283	  customer: Customer,
284	  state: ScenarioState,
285	  stepIndex: number,
286	): StepOutcome => ({
287	  result: {
288	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
289	  },
290	  state: withPolicy(
291	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
292	    stepIndex,
293	    {
294	      items: step.items,
295	      remainingCap: CAP_MULTIPLE * insuranceSum(step.items),
296	    },
297	  ),
298	});
299	
300	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
301	
302	const REDUCED_REIMBURSEMENT_RATE = 0.5;
303	
304	const FULL_REIMBURSEMENT_RATE = 1;
305	
306	// Reads enchantment like the premium-side surcharge rule, but is a different
307	// rule with its own level: this one halves what a claim pays out, that one
308	// raises what a policy costs. Sharing a predicate would tie two levels that the
309	// spec lets move independently, so the shape is repeated deliberately.
310	const qualifiesForReducedReimbursement = (item: Item): boolean =>
311	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT;
312	
313	// The reimbursement rate is decided first, then one deductible comes off.
314	const reimbursementRate = (item: Item): number =>
315	  qualifiesForReducedReimbursement(item)
316	    ? REDUCED_REIMBURSEMENT_RATE
317	    : FULL_REIMBURSEMENT_RATE;
318	
319	const payoutForDamage = (damage: Damage, item: Item): number =>
320	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
321	
322	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
323	  // A claim naming a policy that does not exist is a spec error case, but no
324	  // test drives it yet. The assertion stands in until one does — at which point
325	  // the missing case becomes the error branch rather than a crash.
326	  const policy = state.policies.get(step.policy)!;
327	  // Finding the damaged item by type is enough while every test insures at
328	  // most one item of a type; the pending two-swords test will say how damage
329	  // entries pair with items when that no longer holds.
330	  const payout = sum(
331	    step.incident.damages.map((damage) =>
332	      payoutForDamage(
333	        damage,
334	        policy.items.find((item) => item.type === damage.itemType)!,
335	      ),
336	    ),
337	  );
338	  const remainingCap = policy.remainingCap - payout;
339	  return {
340	    result: { payout, remainingCap },
341	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
342	  };
343	};
344	
345	// Dispatch decides once what a step is; each operation then owns both its
346	// result and how it advances the state, so no caller has to re-test step.op to
347	// know what the step did.
348	const runStep = (
349	  step: Step,
350	  customer: Customer,
351	  state: ScenarioState,
352	  stepIndex: number,
353	): StepOutcome =>
354	  step.op === "quote"
355	    ? runQuote(step, customer, state, stepIndex)
356	    : runClaim(step, state);
357	
358	// The fold carries both halves of the outcome: the results accumulated so far
359	// and the state the next step will see. Threading the state explicitly (rather
360	// than recovering it from the last result) keeps the dependency between steps
361	// visible in the type.
362	interface ScenarioRun {
363	  results: StepResult[];
364	  state: ScenarioState;
365	}
366	
367	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
368	
369	const appendStep =
370	  (customer: Customer) =>
371	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
372	    const outcome = runStep(step, customer, run.state, stepIndex);
373	    return {
374	      results: [...run.results, outcome.result],
375	      state: outcome.state,
376	    };
377	  };
378	
379	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
380	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
381	});
